// Formatting library for C++ - C API implementation
//
// Copyright (c) 2012 - present, Victor Zverovich
// All rights reserved.
//
// For the license information refer to format.h.

#include "fmt/fmt-c.h"

#include <exception>

#include "fmt/args.h"
#include "fmt/format.h"

namespace {

void make_args(fmt::dynamic_format_arg_store<fmt::format_context>& store,
               const fmt_arg* args, size_t num_args) {
  for (size_t i = 0; i < num_args; ++i) {
    const fmt_arg& a = args[i];
    switch (a.type) {
    case fmt_type_int: store.push_back(a.value.int_value); break;
    case fmt_type_uint: store.push_back(a.value.uint_value); break;
    case fmt_type_bool: store.push_back(a.value.bool_value); break;
    case fmt_type_char: store.push_back(a.value.char_value); break;
    case fmt_type_double: store.push_back(a.value.double_value); break;
    case fmt_type_long_double:
      store.push_back(a.value.long_double_value);
      break;
    case fmt_type_string:
      store.push_back(fmt::string_view(a.value.string_value));
      break;
    case fmt_type_pointer: store.push_back(a.value.pointer_value); break;
    }
  }
}

}  // namespace

extern "C" {

int fmt_vformat(char* buffer, size_t size, const char* fmt,
                const fmt_arg* args, size_t num_args) {
  try {
    fmt::dynamic_format_arg_store<fmt::format_context> store;
    make_args(store, args, num_args);
    if (size == 0) {
      return static_cast<int>(
          fmt::vformat_to_n(buffer, 0, fmt::string_view(fmt), store).size);
    }
    auto result =
        fmt::vformat_to_n(buffer, size - 1, fmt::string_view(fmt), store);
    *result.out = '\0';
    return static_cast<int>(result.size);
  } catch (...) {
    return -1;
  }
}

int fmt_vfprint(FILE* f, const char* fmt, const fmt_arg* args,
                size_t num_args) {
  try {
    fmt::dynamic_format_arg_store<fmt::format_context> store;
    make_args(store, args, num_args);
    auto s = fmt::vformat(fmt::string_view(fmt), store);
    if (fwrite(s.data(), 1, s.size(), f) != s.size()) return -1;
    return static_cast<int>(s.size());
  } catch (...) {
    return -1;
  }
}

}  // extern "C"
